const d=$input.first().json;
const demo=d.demo_test===true && typeof d.name==='string' && d.name.trim().length>=2 && d.phone==='CONFIGURE_TEST_NUMBER' && /^demo-[a-z0-9-]{1,90}$/.test(d.request_id);
if(!demo) return [{json:{...d,booking_write_ready:false,note:'Only an explicitly confirmed booking to the verified test phone may reach calendar creation.'}}];
const id='nile'+Array.from(d.request_id).map(c=>c.codePointAt(0).toString(16).padStart(6,'0')).join('');
return [{json:{...d,booking_write_ready:true,calendar_event_id:id}}];

const d=$input.first().json;
const original=$('Normalize request').first().json;
const booking=original.intent==='booking';
const reason=booking?(d.error?.message??d.message??(d.alternative_lookup_failed?'Calendar alternatives lookup failed':'Calendar booking check or creation failed')):'Customer complaint/refund/issue';
return [{json:{...original,details:booking?reason:original.details??original.question,case_status:'needs_human',refund_approved:false,follow_up_reason:reason,staff_notification:'case_logged_not_sent'}}];

const d=$input.first().json;
const caseLogged=!d.error;
return [{json:{...d,case_logged:caseLogged,staff_notification:caseLogged?'case_logged_not_sent':'case_log_failed'}}];

const body = $input.first().json.body ?? $input.first().json;
const intentRaw = String(body.intent ?? (body.date && body.time ? 'booking' : 'issue')).trim().toLowerCase();
const intent = ['check_availability','book_appointment','booking'].includes(intentRaw) ? 'booking' : intentRaw;
const serviceRaw = String(body.service ?? 'cleaning').trim().toLowerCase();
const service = ['battery','battery_change','battery_test'].includes(serviceRaw) ? 'battery' : ['puncture','tire_repair'].includes(serviceRaw) ? 'puncture' : ['tire','tires','tire_replacement','balancing'].includes(serviceRaw) ? 'tires' : ['assessment','unknown_repair'].includes(serviceRaw) ? 'assessment' : serviceRaw;
const rawPhone=String(body.phone??'').trim().replace(/[\s()-]/g,'');
const phone=/^01\d{9}$/.test(rawPhone)?'+20'+rawPhone.slice(1):/^20\d{10}$/.test(rawPhone)?'+'+rawPhone:rawPhone;
return [{json:{intent,service,date:String(body.date??''),time:String(body.time??''),name:String(body.name??'').trim(),phone,question:String(body.question??'').trim(),confirmed:body.confirmed===true,demo_test:body.demo_test===true,supported:body.supported===true,request_id:String(body.request_id??''),details:body.details??null}}];

const d=$input.first().json;
const durations={cleaning:60,battery:30,puncture:60,tires:90,assessment:30};
const duration=durations[d.service];
const datePattern=/^\d{4}-\d{2}-\d{2}$/;
const timePattern=/^(?:[01]\d|2[0-3]):[0-5]\d$/;
let valid=!!duration && datePattern.test(d.date) && timePattern.test(d.time);
let reason='';
if (!duration) reason='Unknown service';
else if (!valid) reason='Please provide a valid date and Cairo time';
if(valid){
  const start=DateTime.fromISO(d.date+'T'+d.time,{zone:'Africa/Cairo'});
  const end=start.plus({minutes:duration});
  const now=DateTime.now().setZone('Africa/Cairo');
  valid=start.isValid && end.isValid && start.toISODate()===d.date && start.toFormat('HH:mm')===d.time && start.weekday!==5 && start.hour>=10 && end.toISODate()===d.date && end.hour<=18 && end.diff(now,'hours').hours>=2 && start.diff(now,'days').days<=30;
  if (!valid) reason='Outside booking policy: Saturday–Thursday, 10:00–18:00 Cairo, 2 hours notice, within 30 days';
  else {d.start=start.toISO();d.end=end.toISO();}
}
return [{json:{...d,duration_minutes:duration??null,valid_booking_request:valid,validation_reason:reason}}];

const request=$('Validate requested service and time').first().json;
const result=$input.first().json;
return [{json:{...request,available:result.available===true?true:result.available===false?false:null,calendar_result:result}}];

const request=$('Validate requested service and time').first().json;
const result=$input.first().json;
return [{json:{...request,available:result.available===true?true:result.available===false?false:null,calendar_result:result}}];

const booking=$('Appointment saved?').first().json;
const request=$('Normalize request').first().json;
const id=String(booking.id??'').trim();
if(!id) throw new Error('Cannot log a customer without a saved calendar event ID');
return [{json:{customer_id:'C-'+id,name:request.name,phone:request.phone,created_at_cairo:DateTime.now().setZone('Africa/Cairo').toISO(),notes:'Booked '+request.service}}];

const booking=$('Appointment saved?').first().json;
const request=$('Normalize request').first().json;
const slot=$('Validate requested service and time').first().json;
const id=String(booking.id??'').trim();
if(!id) throw new Error('Cannot log an appointment without a saved calendar event ID');
return [{json:{booking_id:id,customer_id:'C-'+id,service:request.service,location:request.service==='cleaning'?'Cleaning':'Repairs & Batteries',calendar_id:request.service==='cleaning'?'CONFIGURE_EMAIL':'CONFIGURE_EMAIL',start_cairo:slot.start,end_cairo:slot.end,status:'confirmed',created_at_cairo:DateTime.now().setZone('Africa/Cairo').toISO(),request_id:request.request_id}}];

const d=$input.first().json;
const ref=String(d.request_id||$execution.id||Date.now());
return [{json:{inquiry_id:'Q-'+ref,created_at_cairo:DateTime.now().setZone('Africa/Cairo').toISO(),customer_id:'',category:d.answer_category||d.intent||'general',question_summary:String(d.question||'').slice(0,500),answer_status:'agent_to_answer',name:d.name||'',phone:d.phone||''}}];

const d=$input.first().json;
const ref=String(d.request_id||$execution.id||Date.now());
const detail=typeof d.details==='string'?d.details:JSON.stringify(d.details??'');
return [{json:{case_id:'CASE-'+ref,created_at_cairo:DateTime.now().setZone('Africa/Cairo').toISO(),customer_id:'',category:d.intent||'issue',issue_summary:String(detail||d.question||'').slice(0,500),status:'needs_human',assigned_to:'',resolved_at_cairo:'',name:d.name||'',phone:d.phone||''}}];

const d=$input.first().json;
const id='nile'+Array.from(d.request_id).map(c=>c.codePointAt(0).toString(16).padStart(6,'0')).join('');
return [{json:{...d,calendar_event_id:id}}];

const request=$('Build retry event ID').first().json;
const existing=$input.first().json;
const start=existing.start?.dateTime??'';
const end=existing.end?.dateTime??'';
const same=DateTime.fromISO(start).toMillis()===DateTime.fromISO(request.start).toMillis() && DateTime.fromISO(end).toMillis()===DateTime.fromISO(request.end).toMillis();
return [{json:{status:same?'already_booked':'request_id_conflict',message:same?'This fictional booking already exists. No duplicate was created.':'This request ID belongs to a different appointment. Use a new request ID.',booking_id:existing.id,service:request.service,date:request.date,time:request.time,sms_status:'not_configured'}}];

const d=$('Calendar check succeeded?').first().json;
const rows=$input.all().map(i=>i.json);
if(rows.some(e=>e.error)) return [{json:{...d,alternative_lookup_failed:true,alternatives:[]}}];
const day=DateTime.fromISO(d.date,{zone:'Africa/Cairo'});
const requested=DateTime.fromISO(d.start,{zone:'Africa/Cairo'});
const step=['battery','assessment'].includes(d.service)?30:60;
const duration=d.duration_minutes;
const events=rows.filter(e=>e.id && e.status!=='cancelled' && e.transparency!=='transparent').map(e=>({
 start:DateTime.fromISO(e.start?.dateTime??(e.start?.date+'T00:00:00'),{zone:'Africa/Cairo'}),
 end:DateTime.fromISO(e.end?.dateTime??(e.end?.date+'T00:00:00'),{zone:'Africa/Cairo'})
})).filter(e=>e.start.isValid&&e.end.isValid);
const choices=[];
for(let minute=10*60;minute+duration<=18*60;minute+=step){
 const start=day.plus({minutes:minute});
 const end=start.plus({minutes:duration});
 if(start.toMillis()===requested.toMillis()||start.diffNow('hours').hours<2) continue;
 if(events.some(e=>start<e.end&&end>e.start)) continue;
 choices.push({date:d.date,time:start.toFormat('HH:mm'),start:start.toISO(),end:end.toISO()});
}
choices.sort((a,b)=>Math.abs(DateTime.fromISO(a.start).toMillis()-requested.toMillis())-Math.abs(DateTime.fromISO(b.start).toMillis()-requested.toMillis()));
return [{json:{...d,alternatives:choices.slice(0,3)}}];

const d=$('Protect against duplicates and conflicts').first().json;
const result=$input.first().json;
return [{json:{...d,final_availability:result.available===true?'free':result.available===false?'busy':'error',calendar_result:result}}];

const raw = $input.first().json ?? {};
const msg = Array.isArray(raw.messages) ? (raw.messages[0] ?? {}) : raw;
const id = String(msg['message-id'] ?? msg.messageId ?? msg.message_id ?? '');
const status = msg.status ?? raw.status;
const error = raw.error?.message ?? raw.error ?? msg['error-text'] ?? msg.errorText ?? '';
const accepted = !error && (String(status) === '0' || (status == null && id.length > 0));
const request = $('Normalize request').first().json;
const booking = $('Appointment saved?').first().json;
return [{ json: {
  sms_id: id,
  booking_id: String(booking.id ?? ''),
  phone: request.phone,
  message_type: 'booking_confirmation',
  provider_status: accepted ? 'accepted' : 'failed',
  requested_at_cairo: DateTime.now().setZone('Africa/Cairo').toISO(),
  delivered_at_cairo: '',
  failure_reason: accepted ? '' : String(error || (status == null ? 'No acceptance ID returned' : 'Vonage status ' + status))
} }];
